from PIL import Image
im = Image.open('r113-t-rules-dark-strip.png').convert('RGB'); px=im.load()
def ink(x,y):
    r,g,b=px[x,y]; return abs(r-40)>8 or abs(g-40)>8 or abs(b-40)>8
def clusters(y0,y1,x0=0,x1=220):
    cols=[x for x in range(x0,x1) if any(ink(x,y) for y in range(y0,y1+1))]
    cl=[]; cur=None
    for x in cols:
        if cur and x==cur[1]+1: cur[1]=x
        else:
            if cur: cl.append(cur)
            cur=[x,x]
    if cur: cl.append(cur)
    return cl
